read_inputs <- function() {
  rows <- strsplit(readLines(file.path("input","cases.csv"))[-1L],",",fixed=TRUE)
  cases <- vapply(rows,function(words) as.integer(words[2L]),integer(1))
  deaths <- vapply(rows,function(words) as.integer(words[3L]),integer(1))
  groups <- contacts <- list()
  for (line in readLines(file.path("input","population.txt"))) {
    words <- strsplit(line," ",fixed=TRUE)[[1L]]
    if (words[1L] == "group") groups[[length(groups)+1L]] <- list(
        name=words[2L],
        population=as.integer(words[3L]),
        fatality=as.numeric(words[4L])
    ) else
      contacts[[length(contacts)+1L]] <- as.numeric(words[-1L])
  }
  interventions <- lapply(
      strsplit(readLines(file.path("input","interventions.txt"))," ",fixed=TRUE),
      function(words) list(day=as.integer(words[1L]),multiplier=as.numeric(words[2L]))
  )
  params <- list(scenario=list(),contact_change=list())
  for (line in readLines(file.path("input","params.txt"))) {
    words <- strsplit(line," ",fixed=TRUE)[[1L]]
    name <- words[1L]
    values <- words[-1L]
    if (name == "scenario") params[[name]][[length(params[[name]])+1L]] <- list(
        name=values[1L],
        multiplier=as.numeric(values[2L])
    ) else if (name == "contact_change")
      params[[name]][[length(params[[name]])+1L]] <- list(
          name=values[1L],
          group=values[2L],
          factor=as.numeric(values[3L])
      ) else if (name %in% c("holdout","death_lag","generation","horizon"))
      params[[name]] <- as.integer(values[1L]) else if (name %in% c("milestones","golden")) params[[name]] <- as.integer(values) else if (name %in% c(
          "beta_grid",
          "rho_grid"
      ))
      params[[name]] <- list(
          as.numeric(values[1L]),
          as.numeric(values[2L]),
          as.integer(values[3L])
      ) else if (name == "nelder_mead")
      params[[name]] <- c(
          as.list(as.numeric(values[1:4])),
          list(as.integer(values[5L]))
      ) else if (name %in% c("initial","simplex")) params[[name]] <- as.numeric(values) else params[[name]] <- as.numeric(values[1L])
  }
  list(
      cases=cases,
      deaths=deaths,
      groups=groups,
      contacts=do.call(rbind,contacts),
      interventions=interventions,
      params=params
  )
}
write_outputs <- function(outputs) {
  dir.create("output",showWarnings=FALSE)
  for (name in names(outputs)) writeLines(outputs[[name]],file.path("output",name),useBytes=TRUE)
}

PHI <- 0.6180339887498949
golden <- function(objective,a,b,iterations) {
  c <- b-PHI*(b-a)
  d <- a+PHI*(b-a)
  fc <- objective(c)
  fd <- objective(d)
  records <- list(c(a,b,c,d,fc,fd))
  for (unused in seq_len(iterations)) {
    if (fc < fd) {
      b <- d
      d <- c
      fd <- fc
      c <- b-PHI*(b-a)
      fc <- objective(c)
    } else {
      a <- c
      c <- d
      fc <- fd
      d <- a+PHI*(b-a)
      fd <- objective(d)
    }
    records[[length(records)+1L]] <- c(a,b,c,d,fc,fd)
  }
  list(point=if (fc < fd) c else d,value=if (fc < fd) fc else fd,records=records)
}
nelder_mead <- function(objective,beta,gamma,delta_beta,delta_gamma,alpha,chi,psi,omega,iterations) {
  points <- list(c(beta,gamma),c(beta+delta_beta,gamma),c(beta,gamma+delta_gamma))
  vertices <- lapply(
      seq_along(points),
      function(i) list(
          number=i-1L,
          beta=points[[i]][1L],
          gamma=points[[i]][2L],
          value=objective(points[[i]][1L],points[[i]][2L])
      )
  )
  initial <- vertices
  serial <- 3L
  records <- list()
  ordered <- function(vertices) vertices[order(
      vapply(vertices,function(vertex) vertex$value,numeric(1)),
      vapply(vertices,function(vertex) vertex$number,integer(1))
  )]
  toward <- function(origin,target,factor) origin+factor*(target-origin)
  for (unused in seq_len(iterations)) {
    vertices <- ordered(vertices)
    first <- vertices[[1L]]
    second <- vertices[[2L]]
    third <- vertices[[3L]]
    centroid <- c((first$beta+second$beta)/2,(first$gamma+second$gamma)/2)
    reflected <- centroid+alpha*(centroid-c(third$beta,third$gamma))
    fr <- objective(reflected[1L],reflected[2L])
    accepted <- NULL
    value <- 0
    operation <- "shrink"
    if (fr < first$value) {
      expanded <- toward(centroid,reflected,chi)
      fe <- objective(expanded[1L],expanded[2L])
      if (fe < fr) {
        accepted <- expanded
        value <- fe
        operation <- "expand"
      } else {
        accepted <- reflected
        value <- fr
        operation <- "reflect"
      }
    } else if (fr < second$value) {
      accepted <- reflected
      value <- fr
      operation <- "reflect"
    } else if (fr < third$value) {
      contracted <- toward(centroid,reflected,psi)
      fc <- objective(contracted[1L],contracted[2L])
      if (fc <= fr) {
        accepted <- contracted
        value <- fc
        operation <- "contract_out"
      }
    } else {
      contracted <- toward(centroid,c(third$beta,third$gamma),psi)
      fc <- objective(contracted[1L],contracted[2L])
      if (fc < third$value) {
        accepted <- contracted
        value <- fc
        operation <- "contract_in"
      }
    }
    if (is.null(accepted)) {
      vertices <- list(first)
      for (vertex in list(second,third)) {
        point <- toward(c(first$beta,first$gamma),c(vertex$beta,vertex$gamma),omega)
        vertices[[length(vertices)+1L]] <- list(
            number=serial,
            beta=point[1L],
            gamma=point[2L],
            value=objective(point[1L],point[2L])
        )
        serial <- serial+1L
      }
    } else {
      vertices <- list(first,second,list(number=serial,beta=accepted[1L],gamma=accepted[2L],value=value))
      serial <- serial+1L
    }
    vertices <- ordered(vertices)
    records[[length(records)+1L]] <- list(operation=operation,vertex=vertices[[1L]])
  }
  list(initial=initial,records=records,vertices=vertices)
}

rk4_step <- function(rates,state,multiplier) {
  h <- 0.25
  half <- h/2
  sixth <- h/6
  k1 <- rates(state,multiplier)
  k2 <- rates(state+half*k1,multiplier)
  k3 <- rates(state+half*k2,multiplier)
  k4 <- rates(state+h*k3,multiplier)
  state+sixth*(((k1+2*k2)+2*k3)+k4)
}
simulate <- function(rates,initial,multipliers,inflows) {
  state <- as.numeric(initial)
  daily <- list()
  for (multiplier in multipliers) {
    state[inflows] <- 0
    for (unused in seq_len(4L)) state <- rk4_step(rates,state,multiplier)
    daily[[length(daily)+1L]] <- state
  }
  daily
}

fmt <- function(value,places=4L) {
  text <- sprintf(paste0("%.",places,"f"),value)
  if (startsWith(text,"-") && as.numeric(text) == 0) substring(text,2L) else text
}
curve_plot <- function(observed,fitted) {
  days <- length(observed)
  largest <- max(observed)
  width <- nchar(as.character(largest))
  grid <- matrix(".",20L,70L)
  for (column in seq.int(0L,69L)) {
    day <- (column*(days-1L)) %/% 69L+1L
    observed_row <- min(19L,(20L*observed[day]) %/% largest)
    fitted_row <- min(19L,floor(20*fitted[day]/largest))
    grid[observed_row+1L,column+1L] <- "o"
    grid[fitted_row+1L,column+1L] <- if (observed_row == fitted_row) "#" else "*"
  }
  lines <- paste("plot observed o fitted * both # days 1",days,"max",largest)
  for (row in seq.int(19L,0L)) {
    label <- as.character((largest*row) %/% 20L)
    lines <- c(lines,paste0(strrep(" ",width-nchar(label)),label," |",paste(grid[row+1L,],collapse="")))
  }
  ticks <- paste(ifelse(seq.int(0L,69L) %% 10L == 0L,"+","-"),collapse="")
  lines <- c(lines,paste0(strrep(" ",width+1L),"+",ticks))
  labels <- rep(" ",70L)
  for (column in seq.int(0L,60L,by=10L)) {
    text <- as.character(1L+(column*(days-1L)) %/% 69L)
    characters <- strsplit(text,"",fixed=TRUE)[[1L]]
    labels[column+seq_along(characters)] <- characters
  }
  c(lines,sub(" +$","",paste0(strrep(" ",width+2L),paste(labels,collapse=""))))
}
